import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { ASOF_PARAM } from '../../api/http';
import { AppSession } from '../../slots/defs/appSession';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useCurrentSheet, useCurrentUser, useSheetInfo } from './session';

// The as-of view of this screen (the `asof` search param; other users' screens are unaffected): while
// it is set, every read of the sheet gives it as it stood at the end of that date, the date standing in
// for its today, and every change is refused (api/http.ts). Setting or clearing it re-reads the sheet.
const isDate = (raw: string) => /^\d{4}-\d{2}-\d{2}$/.test(raw) && !Number.isNaN(Date.parse(`${raw}T00:00:00Z`));

function AsOfView() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setAsOf] = useSearchParam(ASOF_PARAM, asString);
  const info = useSheetInfo();
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const shown = info.data?.id === sheet ? info.data : undefined;

  const change = async (next: string | undefined) => {
    await setAsOf(next);
    await queryClient.resetQueries({ queryKey: ['sheet', sheet] });
  };

  if (!user || !sheet) return null;
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (isDate(date.trim())) void change(date.trim());
      }}
    >
      <span>
        As of <strong data-testid="sheet-asof">{shown?.asOf ?? ''}</strong>
      </span>
      <input data-testid="asof-date" placeholder="YYYY-MM-DD" value={date} onChange={(e) => setDate(e.target.value)} />
      <button type="submit" data-testid="asof-set">
        Set as-of
      </button>
      <button type="button" data-testid="asof-clear" onClick={() => void change(undefined)}>
        Clear as-of
      </button>
    </form>
  );
}

export const contribution = AppSession.fill({ order: 25, Component: AsOfView });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';

// The signed-in name and the active sheet id live in the URL (search params `user` and `sheet`).
// Everything else in the app is kept per sheet: a feature reads the sheet id from here and keys
// its queries under ['sheet', sheetId, ...], so loading a sheet re-reads all of them.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

// The active sheet as the store holds it: its id, its today and whether it is archived (then every
// change on it is refused). Every date decision and default
// date in the app uses the sheet's today (useSheetToday), never the browser's clock. In an as-of view
// (asof.slot.tsx) it is the sheet as it stood at the end of `asOf`, and that date is its today. Its
// lastBatch is the number of its last bulk settle batch (null while it has had none). departedTags are the tags of
// claims that have left the sheet (with a person transferred away), sorted; empty as of a date.
export type SheetInfo = {
  id: string; today: string; archived: boolean; asOf: string | null; lastBatch: number | null; departedTags: string[];
};

export const sheetQueryKey = (sheetId: string) => ['sheet', sheetId, 'info'] as const;

export function useSheetInfo() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: sheetQueryKey(sheet ?? ''),
    queryFn: () => getJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet ?? '')}`),
    enabled: !!sheet,
  });
}

/** The sheet's today (YYYY-MM-DD), or undefined until the sheet is loaded. */
export const useSheetToday = () => useSheetInfo().data?.today;
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx answer: its status tells a refusal (400) from a conflict with someone else's save (409).
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

// The as-of view: while the screen's `asof` search param holds a date, every read of a sheet asks for the
// sheet as it stood at the end of that date, and every change is refused here, before it reaches the store
// (so each form and action shows its usual error). Loading a sheet (PUT /api/sheets/<id>) is not a change.
export const ASOF_PARAM = 'asof';

/** The date the screen shows the sheet as of (YYYY-MM-DD), or '' while it shows the sheet as it is now. */
export function currentAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get(ASOF_PARAM) ?? '';
  try {
    const parsed: unknown = JSON.parse(raw);
    return typeof parsed === 'string' ? parsed : raw;
  } catch {
    return raw;
  }
}

const isSheetLoad = (path: string) => /^\/api\/sheets\/[^/?]+$/.test(path);

async function send<T>(path: string, init?: RequestInit, live = false): Promise<T> {
  const asOf = live ? '' : currentAsOf();
  if (asOf && init?.method && init.method !== 'GET' && !isSheetLoad(path)) {
    throw new HttpError(`${init.method} ${path} -> refused while the sheet is shown as of ${asOf}`, 400);
  }
  if (asOf && !init?.method && path.startsWith('/api/sheets/')) {
    path += `${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A read of the store as it is now, whatever date the screen shows the sheet as of.
export function getJsonLive<T>(path: string): Promise<T> {
  return send<T>(path, undefined, true);
}

// A change sends the signed-in name (`user`) as `X-User`, URI-encoded (a header is Latin-1 only),
// so the server records who made it.
const jsonHeaders = (user?: string): Record<string, string> =>
  user ? { 'Content-Type': 'application/json', 'X-User': encodeURIComponent(user) } : { 'Content-Type': 'application/json' };

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body?: unknown, user?: string, live = false): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: jsonHeaders(user),
    body: body === undefined ? undefined : JSON.stringify(body),
  }, live);
}

// A change that is not a change to the sheet (a user's own preference): made whatever date the screen shows the
// sheet as of.
export function putJsonLive<T>(path: string, body?: unknown, user?: string): Promise<T> {
  return putJson<T>(path, body, user, true);
}
