package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads the sheet by id, starting an empty one when the id was never used. */
public class LoadOrCreateSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository, Out<Sheet> sheetOut) {
        String id = sheetId.trim();
        sheetOut.set(repository.findById(id).orElseGet(() -> repository.save(new Sheet(id))));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.claim.Tags;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.history.AsOf;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet; as of a date (asOf), as it stood at the end of it: that date its today, the date itself, and its last
 *  bulk settle batch then (the highest batch its claims then carried). */
public class RespondWithSheet {

    /** @param asOf the date the sheet is shown as of (null: as it stands now).
     *  @param lastBatch the number of the sheet's last bulk settle batch (null: none yet).
     *  @param departedTags the tags of claims that have left the sheet, sorted (empty as of a date). */
    public record SheetResponse(String id, String today, boolean archived, String asOf, Integer lastBatch,
            List<String> departedTags) {
    }

    public void respond(@Val Sheet sheet, @RequestParam(name = "asOf", required = false) String asOfParam, AsOf asOf,
            ObjectResponse<SheetResponse> response) throws InvalidTodayException {
        LocalDate date = AsOf.dateOf(asOfParam);
        Sheet view = asOf.sheet(sheet, date);
        Integer lastBatch = date == null
                ? (sheet.getLastSettleBatch() == 0 ? null : sheet.getLastSettleBatch())
                : asOf.claims(sheet.getId(), date).stream().map(Claim::getSettleBatch).filter(Objects::nonNull)
                        .max(Integer::compare).orElse(null);
        response.send(new SheetResponse(view.getId(), view.getToday().toString(), view.isArchived(),
                date == null ? null : date.toString(), lastBatch,
                date == null ? Tags.list(sheet.getDepartedTags()) : List.of()));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.history.AsOf;
import net.officefloor.hq.app.sheet.InvalidTodayException;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's claims; as of a date (asOf), as they stood at the end of it (only the comments written and lines added by then). */
public class RespondWithClaims {
    public void respond(@Val Sheet sheet, @RequestParam(name = "asOf", required = false) String asOfParam, AsOf asOf,
            ClaimCommentRepository comments, ClaimLineRepository claimLines,
            ObjectResponse<List<ClaimResponse>> response) throws InvalidTodayException {
        LocalDate date = AsOf.dateOf(asOfParam);
        Map<Long, List<String>> lines = asOf.claimLines(sheet.getId(), date);
        Map<Long, List<String>> lined = claimLines.linesOnSheet(sheet.getId(), date);
        Map<Long, List<String>> commented = comments.linesOnSheet(sheet.getId(), date);
        response.send(asOf.claims(sheet.getId(), date).stream()
                .map(c -> ClaimResponse.from(c, lines.getOrDefault(c.getId(), List.of()),
                        commented.getOrDefault(c.getId(), List.of()),
                        lined.getOrDefault(c.getId(), List.of()))).toList());
    }
}
