package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.StatementRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, StatementRepository statements, PatronRepository patrons, PersonAliasRepository aliases,
            PersonGradeRepository grades, SheetRepository sheets, TreeNames tree,
            ObjectResponse<PersonResponse> response) {
        Sheet sheet = sheets.findById(person.getSheetId()).orElseGet(() -> new Sheet(person.getSheetId()));
        response.send(PersonResponse.from(person, statements.ofPerson(person.getId()),
                patrons.findByPersonIdOrderByIdAsc(person.getId()),
                aliases.findByPersonIdOrderByIdAsc(person.getId()), grades.gradesOf(person), sheet.getToday(),
                tree.usedAround(sheet.getId())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.StatementRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with the person merged into, as they now stand. */
public class RespondWithMergedInto {
    public void respond(@Val PersonMerged merged, StatementRepository statements, PatronRepository patrons,
            PersonAliasRepository aliases, PersonGradeRepository grades, SheetRepository sheets, TreeNames tree,
            ObjectResponse<PersonResponse> response) {
        Person into = merged.into();
        Sheet sheet = sheets.findById(into.getSheetId()).orElseGet(() -> new Sheet(into.getSheetId()));
        response.send(PersonResponse.from(into, statements.ofPerson(into.getId()),
                patrons.findByPersonIdOrderByIdAsc(into.getId()),
                aliases.findByPersonIdOrderByIdAsc(into.getId()), grades.gradesOf(into), sheet.getToday(),
                tree.usedAround(sheet.getId())));
    }
}
package net.officefloor.hq.app.plan;

import java.util.List;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** The sheet's plans, in the order they were added. */
public class RespondWithPlans {
    public void respond(@Val Sheet sheet, PlanRepository plans, PlanClaimRepository made, PlanPauseRepository pauses,
            PlanChangeRepository changes,
            ObjectResponse<List<PlanResponse>> response) {
        response.send(plans.findBySheetIdOrderByIdAsc(sheet.getId()).stream()
                .map(p -> PlanResponse.of(p, sheet.getToday(), made, pauses, changes)).toList());
    }
}
