    /** Works out the sheet's figures now; a sheet not yet stored has none. */
    public static Rollup of(String sheetId, SheetRepository sheets, PersonRepository persons,
            ClaimRepository claims, RateRepository rates, PersonGradeRepository grades, AsOf asOf) {
        String id = sheetId.trim();
        Optional<Sheet> sheet = sheets.findById(id);
        Map<Long, Figures> people = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        if (sheet.isPresent()) {
            List<Claim> all = claims.findBySheetIdOrderByIdDesc(id);
            var sheetRates = rates.findInChain(id);
            Map<Long, List<PersonGrade>> dated = grades.datedOnSheet(id);
            List<Person> listed = persons.findListed(id);
            Map<Long, BigDecimal> held = new LinkedHashMap<>();
            Map<Long, BigDecimal> cuts = PoolCuts.totalsByPerson(sheet.get(), asOf);
            for (Person owner : listed) {
                ClaimFigures ownerFigures = new ClaimFigures(sheetRates,
                        new PersonGrades(owner.getGrade(), dated.getOrDefault(owner.getId(), List.of())), sheet.get());
                all.stream().filter(c -> owner.getId().equals(c.getPersonId()) && c.getShares() != null
                        && ClaimFigures.countsLive(c, owner, sheet.get().getToday())).forEach(c -> {
                            BigDecimal claimDue = ownerFigures.due(c);
                            if (claimDue != null) {
                                ClaimShares.of(c).forEach(s -> held.merge(s.personId(),
                                        ClaimShares.part(claimDue, s.share()), BigDecimal::add));
                            }
                        });
            }
            for (Person person : listed) {
                List<Claim> mine = all.stream().filter(c -> person.getId().equals(c.getPersonId())).toList();
                BigDecimal claimed = mine.stream()
                        .filter(c -> c.getCorrects() == null && ClaimFigures.countsClaimed(c, person, sheet.get().getToday())).map(Claim::getAmount)
                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
                ClaimFigures figures = new ClaimFigures(sheetRates,
                        new PersonGrades(person.getGrade(), dated.getOrDefault(person.getId(), List.of())), sheet.get());
                String due = figures.dueTotal(mine, sheet.get().getToday(), person, held.get(person.getId()),
                        cuts.get(person.getId()));
                BigDecimal overdue = mine.stream()
                        .filter(c -> ClaimFigures.countsLive(c, person, sheet.get().getToday()) && figures.overdue(c))
                        .map(figures::due).filter(d -> d != null)
                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
                BigDecimal settled = mine.stream()
                        .filter(c -> ClaimFigures.countsLive(c, person, sheet.get().getToday()) && c.getStatus() == ClaimStatus.SETTLED
                                && c.getCorrects() == null)
                        .map(figures::due).filter(d -> d != null)
        return liveFigure(claim);
    }

    /** The claim's live figure: neither frozen nor bound; null when it has none (n/a). */
    private BigDecimal liveFigure(Claim claim) {
        return rateOn(grades.on(claim.getDate()), claim)
                .map(pct -> rateFigure(claim.getAmount(), pct, rounding(claim)))
                .orElse(null);
    }

    /** The claim's due less its holders' parts (each its due times their share divided by 100, rounded half to
     *  even): what its own person's due-total counts of it; null when it has none (n/a). */
    public BigDecimal ownDue(Claim claim) {
        BigDecimal due = due(claim);
        return due == null ? null : due.subtract(ClaimShares.parts(claim, due));
    }

    /** The person's due-total: their counted claims' dues (with any late charge) added up, 0.00 with none; n/a when their grade
     *  in force on the day has no rate in force then, unless a counted claim keeps a figure: a fixed one (settled or bound), or a
     *  live one at another grade they had on its date, or one dated on or before the day (at a rate that has ended since). */
    public String dueTotal(List<Claim> claims, LocalDate today) {
        return dueTotal(claims, today, null);
    }

    /** The person's live due-total, as {@link #dueTotal(List, LocalDate)}; their OPEN claims do not count once their
     *  retirement date is reached, unless a statement binds them. At most the sheet's cap (n/a is not capped). */
    public String dueTotal(List<Claim> claims, LocalDate today, Person person) {
        return dueTotal(claims, today, person, null);
    }

    /** The person's live due-total, as {@link #dueTotal(List, LocalDate, Person)}, with their parts of the claims of
     *  others shared with them (null: they hold no share of a counted claim) added before the cap: their own claims
     *  count less the holders' parts, and when they would have none (n/a) their parts are their due-total. */
    public String dueTotal(List<Claim> claims, LocalDate today, Person person, BigDecimal held) {
        return dueTotal(claims, today, person, held, null);
    }

    /** The person's live due-total, as {@link #dueTotal(List, LocalDate, Person, BigDecimal)}, with the cap covering
     *  it plus their cut total (null: none): it is held to the cap less their cut total, not below 0.00. */
    public String dueTotal(List<Claim> claims, LocalDate today, Person person, BigDecimal held, BigDecimal cut) {
        String sum = uncappedDueTotal(claims, today, person);
        if (held != null) {
            sum = ("n/a".equals(sum) ? held : new BigDecimal(sum).add(held)).setScale(2).toPlainString();
        }
        if (cap == null || "n/a".equals(sum)) {
            return sum;
        }
        BigDecimal limit = cut == null ? cap : cap.subtract(cut).max(BigDecimal.ZERO);
        if (new BigDecimal(sum).compareTo(limit) <= 0) {
            return sum;
        }
        return limit.setScale(2).toPlainString();
    }

    /** The person's live due-total before the cap: the sum of their figures. */
    private String uncappedDueTotal(List<Claim> claims, LocalDate today, Person person) {
        List<Claim> counted = claims.stream().filter(c -> countsLive(c, person, today)).toList();
        String grade = grades.on(today);
        boolean kept = counted.stream().anyMatch(c -> c.getDue() != null || (c.isBound() && c.getStatedDue() != null)
                || (!c.isBound() && (!grade.equals(grades.on(c.getDate())) || !c.getDate().isAfter(today)) && figure(c) != null));
        if (rateOn(grade, today).isEmpty() && !kept) {
            return "n/a";
        }
        return counted.stream().map(this::ownDue).filter(f -> f != null)
                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2).toPlainString();
    }
}

